contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // param callerIsOwner: if true, the test will attempt the suicide call as the owner (the deploying address of C);
    // otherwise the test will attempt it as a non-owner by using this contract which is NOT the original deployer.
    // amount: Ether sent to C before the suicide attempt to observe balance effects.
    function run(bool callerIsOwner, uint amount) public payable {
        require(address(this).balance >= amount);
        // initially fund the target contract c with `amount` wei so selfdestruct would transfer value if it runs
        // Only the test contract can send funds to c here by calling payable address
        (bool sent, ) = address(c).call{value: amount}(""");
        // funding must succeed for the scenario to be meaningful
        require(sent);

        // read pre-state
        uint beforeBalance = address(c).balance;
        address owner = c.smartfix_owner();

        // Decide caller: if callerIsOwner, we need to simulate call coming from owner.
        // But the checker deploys c fresh and owner is the deployer (external account), not this contract.
        // We cannot change msg.sender when calling c from here; therefore if callerIsOwner is true
        // we expect the call to revert (since this contract is not the owner), and if false it must revert as well.
        // However, a meaningful general property we can assert: only an address equal to smartfix_owner could possibly succeed,
        // meaning that if msg.sender != smartfix_owner then the call must revert and balance unchanged.

        // Make the call and capture whether it reverted when invoked from this contract (which is not the owner in general)
        bool reverted;
        try c.sudicideAnyone{value: 0}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempt, read post-state
        uint afterBalance = address(c).balance;

        // General rule: if this contract is not the owner (msg.sender != smartfix_owner), then calling sudicideAnyone from this contract must revert and must not change c's balance.
        assert((address(this) != owner) ? (reverted && afterBalance == beforeBalance) : true);
    }

    receive() external payable {}
}

