contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // single public function with inputs: caller address candidate to call sudicideAnyone
    // We simulate calls by proxying via low-level call: since the checker will deploy c and
    // then deploy this test contract, msg.sender for calls on c will be this contract.
    // To model owner vs non-owner behavior we use a boolean parameter: if true, we first
    // attempt to make this contract be the owner by reading c.smartfix_owner (which was set
    // at C construction to the address that deployed C). We cannot change that owner here,
    // so we assert the observable rule: if this contract is owner, calling sudicideAnyone must
    // not revert and must transfer c.balance to address(this); if not owner, the call must revert.
    function run() public payable {
        // no precondition
        // read who the owner is
        address owner = c.smartfix_owner();

        // prepare to call sudicideAnyone and capture whether it reverts
        bool reverted;
        // calling c.sudicideAnyone() will attempt to selfdestruct to msg.sender (this contract)
        // and is guarded by require(smartfix_owner == msg.sender)
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call: if this contract was the owner, the call should not have reverted,
        // and the contract C should have been selfdestructed sending its balance to this contract.
        // If this contract was not the owner, the call must have reverted and c must still exist
        // (i.e. its balance unchanged). We can only observe address(c).balance and address(this).balance.

        uint balC = address(c).balance;
        uint balThis = address(this).balance;

        // General rule asserted for all inputs (there are none):
        // If this contract equals owner then the call did not revert and C's balance was transferred (so balC==0 and balThis increased at least by previous balC).
        // If this contract is not owner then the call reverted and balC is unchanged (since we cannot know previous balances here, we infer revert implies balC unchanged by requiring reverted == (owner != address(this))).
        // Express as: reverted iff caller is not owner, and if not reverted then balC==0.
        assert((reverted && owner != address(this)) || (!reverted && owner == address(this) && balC == 0));
    }

    receive() external payable {}
}

